using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;
public static class FullRosterMotionPacketReplay {
 [Serializable]class Header {public string[] nodeNames;public int[] parents;public int loopFrames,transitionFrames;public float loopDuration,danceDuration;}
 sealed class Packet {public Header h;public float[] data;public int frames;public float duration;}
 static readonly Dictionary<string,Packet> Cache=new Dictionary<string,Packet>();
 static Packet Get(string role,string clip){string key=role+"/"+clip;if(Cache.TryGetValue(key,out var p))return p;string root=Path.GetFullPath("../art/drafts/full-roster-v1/"+role+"-motion-continuity/");var h=JsonUtility.FromJson<Header>(File.ReadAllText(root+"report.json"));bool guard=clip=="GuardLoop";if(!guard&&clip!="GuardDanceReturn")throw new ArgumentException("Unknown pose packet");var bytes=File.ReadAllBytes(root+clip+".bin");p=new Packet{h=h,frames=guard?h.loopFrames:h.transitionFrames,duration=guard?h.loopDuration:h.danceDuration,data=new float[bytes.Length/4]};Buffer.BlockCopy(bytes,0,p.data,0,bytes.Length);if(p.data.Length!=p.frames*h.nodeNames.Length*10)throw new Exception("Packet length mismatch");Cache.Add(key,p);return p;}
 public static float Duration(string role,string clip)=>Get(role,clip).duration;
 public static void Apply(GameObject actor,string role,string clip,float seconds){var p=Get(role,clip);var nodes=actor.GetComponentsInChildren<Transform>(true);if(nodes.Length!=p.h.nodeNames.Length)throw new Exception("Packet hierarchy length changed");float frame=Mathf.Clamp01(seconds/p.duration)*(p.frames-1);int a=Math.Min(p.frames-2,(int)frame),b=a+1;float t=frame-a;for(int i=0;i<nodes.Length;i++){if(i>0&&nodes[i].name!=p.h.nodeNames[i])throw new Exception("Packet named hierarchy changed");if(Array.IndexOf(nodes,nodes[i].parent)!=p.h.parents[i])throw new Exception("Packet parent changed");int x=(a*nodes.Length+i)*10,y=(b*nodes.Length+i)*10;nodes[i].localPosition=Vector3.Lerp(new Vector3(p.data[x],p.data[x+1],p.data[x+2]),new Vector3(p.data[y],p.data[y+1],p.data[y+2]),t);nodes[i].localRotation=Quaternion.Slerp(new Quaternion(p.data[x+3],p.data[x+4],p.data[x+5],p.data[x+6]),new Quaternion(p.data[y+3],p.data[y+4],p.data[y+5],p.data[y+6]),t);nodes[i].localScale=Vector3.Lerp(new Vector3(p.data[x+7],p.data[x+8],p.data[x+9]),new Vector3(p.data[y+7],p.data[y+8],p.data[y+9]),t);}}
}
